import mongoose from 'mongoose';

/**
 * A detected trading opportunity surfaced by the Opportunity Scanner.
 * Opportunities are generated by a background job across many symbols, ranked
 * by confidenceScore, and expire after a while so the board stays fresh.
 */

const opportunitySchema = new mongoose.Schema(
  {
    symbol: { type: String, required: true, index: true },
    market: {
      type: String,
      enum: ['forex', 'crypto', 'indices', 'commodities', 'synthetic'],
      required: true,
      index: true,
    },
    timeframe: { type: String, required: true, index: true },
    currentPrice: Number,

    setupType: {
      type: String,
      enum: ['order-block', 'fair-value-gap', 'breaker-block', 'liquidity-sweep', 'trend-continuation', 'reversal'],
      required: true,
    },
    direction: { type: String, enum: ['BUY', 'SELL'], required: true },
    confidenceScore: { type: Number, min: 0, max: 100, required: true, index: true },
    riskLevel: { type: String, enum: ['low', 'medium', 'high'], default: 'medium', index: true },

    entry: Number,
    stopLoss: Number,
    takeProfit1: Number,
    takeProfit2: Number,
    riskRewardRatio: String,

    rationale: String,
    confluences: [String],
    strategyMatched: { type: String, default: 'SMC' }, // SMC, ICT, Price-Action, or Nom de la Stratégie Personnalisée
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
      index: true,
    }, // null if global SMC scan, or specific user ID if custom strategy/plan scan
    emailSent: { type: Boolean, default: false },

    status: {
      type: String,
      enum: ['active', 'expired', 'triggered', 'closed'],
      default: 'active',
      index: true,
    },
    outcome: {
      type: String,
      enum: ['pending', 'hit_tp1', 'hit_tp2', 'hit_sl', 'closed_profit', 'closed_loss'],
      default: 'pending',
      index: true,
    },
    pnlPips: { type: Number, default: 0 },
    closedAt: { type: Date, default: null },
    closedPrice: { type: Number, default: null },
    zones: [
      {
        zoneType: { type: String, default: 'order-block' }, // order-block, fvg, liquidity, breaker
        priceMin: Number,
        priceMax: Number,
        label: String,
        color: String,
      },
    ],
    detectedAt: { type: Date, default: Date.now },
    expiresAt: { type: Date, index: true },
  },
  {
    timestamps: true,
    toJSON: { virtuals: true },
    toObject: { virtuals: true },
  }
);

opportunitySchema.index({ status: 1, confidenceScore: -1 });
opportunitySchema.index({ market: 1, timeframe: 1, confidenceScore: -1 });

// Virtual: whether this opportunity is still fresh.
opportunitySchema.virtual('isActive').get(function () {
  return this.status === 'active' && (!this.expiresAt || this.expiresAt > new Date());
});

const Opportunity = mongoose.model('Opportunity', opportunitySchema);

export default Opportunity;
